cd /workspace; python3 -I - <<'EOF'
import sys, json, re, sqlite3
sys.path.insert(0,".")
from reproductions.sql_credit.workload import make_case, database, execute

def case_from_gts(g):
    s,i=g.rsplit("-",1); return make_case(s,int(i))

def parse_calls(out):
    calls=[]
    for m in re.finditer(r"<tool_call>\n(.*?)\n</tool_call>", out, re.S):
        try:
            obj=json.loads(m.group(1))
            if isinstance(obj.get("arguments"), str):
                args=json.loads(obj["arguments"])
            else: args=obj.get("arguments") or {}
            calls.append(args)
        except Exception as e:
            calls.append({"parse_error":str(e),"raw":m.group(1)[:100]})
    return calls

def parse_resps(out):
    return re.findall(r"<tool_response>\n(.*?)\n</tool_response>", out, re.S)

for step in (1,2,3):
    rows=[json.loads(l) for l in open(f"observed_run/rollouts/{step}.jsonl")]
    prompt_ok=0; tool_ok=0; tool_tot=0; mism=[]
    for r in rows:
        c=case_from_gts(r["gts"])
        # prompt check: user question should be in input
        if c.question in r["input"]: prompt_ok+=1
        else: mism.append(("prompt",r["gts"]))
        calls=parse_calls(r["output"]); resps=parse_resps(r["output"])
        for args,resp in zip(calls,resps):
            if args.get("action")!="query": continue
            q=args.get("query","")
            tool_tot+=1
            conn=database(c.seed)
            try:
                expected={"rows":execute(conn,q,max_rows=80)}
            except Exception as e:
                expected={"error":str(e)[:200]}
            finally: conn.close()
            try: got=json.loads(resp)
            except Exception: got=None
            if got==expected: tool_ok+=1
            elif len(mism)<6: mism.append(("tool",r["gts"],q[:80],str(expected)[:120],str(got)[:120]))
    print(f"step {step}: prompts match {prompt_ok}/{len(rows)}, tool responses match recompute {tool_ok}/{tool_tot}")
    for m in mism[:4]: print("   MISMATCH",m)
EOF

