            q=args.get("query","")
            tool_tot+=1
            conn=database(c.seed)
            try:
                expected={"rows":execute(conn,q,max_rows=80)}
            except Exception as e:
                expected={"error":str(e)[:200]}
            finally: conn.close()
            try: got=json.loads(resp)
            except Exception: got=None
            if got==expected: tool_ok+=1
            elif len(mism)<6: mism.append(("tool",r["gts"],q[:80],str(expected)[:120],str(got)[:120]))
    print(f"step {step}: prompts match {prompt_ok}/{len(rows)}, tool responses match recompute {tool_ok}/{tool_tot}")
    for m in mism[:4]: print("   MISMATCH",m)
EOF

